#!/usr/bin/env node
// Distributes the canonical harness in harness/ to the tool-specific directories
// Claude Code, opencode, and Antigravity (the `agy` CLI) each read.
//
// harness/ is the only place an agent charter or a skill is edited. The generated
// copies under .claude/, .opencode/, and .agents/ are committed so the workspace works
// on a fresh clone with no build step, and regenerated by running this script.
//
// Agent charters carry tool-neutral frontmatter. Each tool needs a different subset
// of it, so charters are transformed rather than copied:
//
//   name, description    all three tools
//   model-tier            Claude Code, as `model:` (high -> opus, standard -> sonnet);
//                          Antigravity, as `model:` (high -> pro, standard -> flash).
//                         opencode resolves the model from opencode.json instead, so that a
//                         workspace pointed at a different provider is not overridden here.
//   claude-tools          Claude Code only, as `tools:`
//   opencode-mode         opencode only, as `mode:`
//   opencode-permission   opencode, as a `permission:` map; Antigravity derives its own
//                         `tools:`/`commandExecutionPolicy:` from the same edit/bash flags
//                         (see deriveAntigravityTools) rather than adding a fourth field to
//                         maintain by hand.
//
// Antigravity's tool identifiers (run_command, replace_file_content, write_to_file, …) and
// its base per-agent grant (view_file, read_url_content, search_web, schedule, send_message,
// generate_image, manage_task — present whether or not `tools:` is set) were confirmed by
// probing a live `agy` install (v1.2.9), not copied from documentation: three independent
// doc fetches gave three different, partly conflicting tool-id lists. Re-verify against
// `agy --version` if this stops matching a newer release.
//
// Skills are the same SKILL.md format across all three tools, so they are copied verbatim.
// Commands are copied verbatim for Claude Code and opencode, which both support `$ARGUMENTS`
// and inline `` !`cmd` `` shell substitution. Antigravity supports neither (confirmed: both
// were passed through unexpanded in a live probe, and OpenSpec's own generated
// `.agents/workflows/opsx-*.md` never use that syntax either — every argument and shell call
// is phrased as an instruction for the agent to act on with its own tools) and has no
// separate "commands" concept — OpenSpec's own antigravity output uses `.agents/workflows/`,
// so ours does too, de-templated (see detemplatizeForAntigravity).
//
// Anything under .claude/, .opencode/, or .agents/ that this script does not own is left
// alone — that is how the openspec-generated opsx workflows and skills survive a sync.

import { readdirSync, readFileSync, writeFileSync, mkdirSync, rmSync, statSync, existsSync } from "node:fs";
import { join, dirname, relative } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const HARNESS = join(ROOT, "harness");

const CLAUDE_MODEL_BY_TIER = { high: "opus", standard: "sonnet" };
const ANTIGRAVITY_MODEL_BY_TIER = { high: "pro", standard: "flash" };

const TARGETS = {
  claude: { agents: ".claude/agents", skills: ".claude/skills", commands: ".claude/commands" },
  opencode: { agents: ".opencode/agent", skills: ".opencode/skills", commands: ".opencode/commands" },
  antigravity: { agents: ".agents/agents", skills: ".agents/skills", commands: ".agents/workflows" },
};

/** Split a markdown file into its frontmatter block and body. */
function splitFrontmatter(text, path) {
  const match = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/.exec(text);
  if (!match) throw new Error(`${path}: no frontmatter block`);
  return { frontmatter: match[1], body: match[2] };
}

/**
 * Read the flat key/value pairs of a frontmatter block. Values are either inline
 * or a YAML folded block (`>-`), whose continuation lines are indented; folded
 * values are rejoined into one line, which is what both tools expect for a
 * description.
 */
function parseFrontmatter(frontmatter, path) {
  const fields = new Map();
  const lines = frontmatter.split(/\r?\n/);

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (!line.trim()) continue;

    const entry = /^([A-Za-z][A-Za-z0-9_-]*):\s*(.*)$/.exec(line);
    if (!entry) throw new Error(`${path}: cannot parse frontmatter line: ${line}`);

    const [, key, inline] = entry;
    if (inline !== ">-" && inline !== ">" && inline !== "|") {
      fields.set(key, inline.trim());
      continue;
    }

    const folded = [];
    while (i + 1 < lines.length && /^\s+\S/.test(lines[i + 1])) {
      folded.push(lines[++i].trim());
    }
    fields.set(key, folded.join(" "));
  }

  return fields;
}

/** Wrap a long value across continuation lines so the generated file stays readable. */
function foldedValue(key, value, width = 96) {
  const out = [];
  let line = "";
  for (const word of value.split(/\s+/)) {
    if (line && line.length + word.length + 1 > width) {
      out.push(line);
      line = word;
    } else {
      line = line ? `${line} ${word}` : word;
    }
  }
  if (line) out.push(line);
  return out.length > 1
    ? `${key}: >-\n${out.map((l) => `  ${l}`).join("\n")}`
    : `${key}: ${value}`;
}

function require_(fields, key, path) {
  const value = fields.get(key);
  if (!value) throw new Error(`${path}: missing required frontmatter key '${key}'`);
  return value;
}

/** Parse `opencode-permission`'s "tool=action, tool=action" shorthand into pairs. */
function parsePermissionPairs(permission, path) {
  return permission
    .split(",")
    .map((pair) => pair.trim())
    .filter(Boolean)
    .map((pair) => {
      const [tool, action] = pair.split("=").map((s) => s.trim());
      if (!tool || !action) throw new Error(`${path}: bad opencode-permission entry '${pair}'`);
      return [tool, action];
    });
}

function renderClaudeAgent(fields, body, path) {
  const head = [
    `name: ${require_(fields, "name", path)}`,
    foldedValue("description", require_(fields, "description", path)),
  ];

  const tools = fields.get("claude-tools");
  if (tools) head.push(`tools: ${tools}`);

  const tier = fields.get("model-tier");
  if (tier) {
    const model = CLAUDE_MODEL_BY_TIER[tier];
    if (!model) throw new Error(`${path}: unknown model-tier '${tier}'`);
    head.push(`model: ${model}`);
  }

  return `---\n${head.join("\n")}\n---\n\n${body.trimStart()}`;
}

function renderOpencodeAgent(fields, body, path) {
  const head = [foldedValue("description", require_(fields, "description", path))];

  head.push(`mode: ${fields.get("opencode-mode") ?? "subagent"}`);

  const permission = fields.get("opencode-permission");
  if (permission) {
    const rules = parsePermissionPairs(permission, path).map(([tool, action]) => `  ${tool}: ${action}`);
    head.push(`permission:\n${rules.join("\n")}`);
  }

  return `---\n${head.join("\n")}\n---\n\n${body.trimStart()}`;
}

/**
 * Antigravity has no equivalent of Claude's `tools:` allowlist-by-name or opencode's
 * `permission:` map — it grants a fixed base toolset to every agent (view_file,
 * read_url_content, search_web, schedule, send_message, generate_image, manage_task,
 * confirmed present whether or not `tools:` is set at all) and additively grants whatever
 * else `tools:` names. So rather than a fourth frontmatter field to keep in sync by hand,
 * its two extra capabilities are derived from the same `opencode-permission` edit/bash
 * flags every charter already carries:
 *
 *   bash: allow  -> run_command                    (shell, tests, the openspec CLI)
 *   edit: allow  -> replace_file_content,
 *                   write_to_file                  (both observed granted together)
 *
 * `commandExecutionPolicy` is set to "auto" only when run_command is actually granted;
 * omitted otherwise, leaving Antigravity's own default (sandbox) in effect for an agent
 * that was never meant to run shell commands.
 */
function deriveAntigravityTools(permission, path) {
  if (!permission) return { tools: [], autoRun: false };

  const flags = new Map(parsePermissionPairs(permission, path));
  const tools = [];
  if (flags.get("bash") === "allow") tools.push("run_command");
  if (flags.get("edit") === "allow") tools.push("replace_file_content", "write_to_file");

  return { tools, autoRun: tools.includes("run_command") };
}

function renderAntigravityAgent(fields, body, path) {
  const head = [
    `name: ${require_(fields, "name", path)}`,
    foldedValue("description", require_(fields, "description", path)),
  ];

  head.push("subagent: true");
  head.push("mainAgent: false");

  const tier = fields.get("model-tier");
  if (tier) {
    const model = ANTIGRAVITY_MODEL_BY_TIER[tier];
    if (!model) throw new Error(`${path}: unknown model-tier '${tier}'`);
    head.push(`model: ${model}`);
  }

  const { tools, autoRun } = deriveAntigravityTools(fields.get("opencode-permission"), path);
  if (tools.length) head.push(`tools:\n${tools.map((t) => `  - ${t}`).join("\n")}`);
  if (autoRun) head.push("commandExecutionPolicy: auto");

  return `---\n${head.join("\n")}\n---\n\n${body.trimStart()}`;
}

/**
 * Antigravity workflows support neither `$ARGUMENTS` substitution nor inline
 * `` !`cmd` `` shell execution — confirmed by probing a live install, where both were
 * passed through unexpanded, and by OpenSpec's own generated `.agents/workflows/opsx-*.md`,
 * which never use either even though its Claude/opencode command output does. Both are
 * rewritten as an instruction for the agent to act on with its own tools instead.
 */
function detemplatizeForAntigravity(body) {
  return body
    .replace(/\$ARGUMENTS/g, "the text the person gave after invoking this workflow, if any")
    .replace(/!`([^`]+)`/g, (_, cmd) => `run \`${cmd}\` yourself and read its output before continuing`);
}

function copyTree(from, to) {
  mkdirSync(to, { recursive: true });
  for (const entry of readdirSync(from)) {
    const src = join(from, entry);
    const dst = join(to, entry);
    if (statSync(src).isDirectory()) copyTree(src, dst);
    else writeFileSync(dst, readFileSync(src));
  }
}

function syncAgents() {
  const source = join(HARNESS, "agents");
  const written = [];

  for (const target of Object.values(TARGETS)) {
    mkdirSync(join(ROOT, target.agents), { recursive: true });
  }

  for (const file of readdirSync(source).filter((f) => f.endsWith(".md")).sort()) {
    const path = join(source, file);
    const { frontmatter, body } = splitFrontmatter(readFileSync(path, "utf8"), path);
    const fields = parseFrontmatter(frontmatter, path);

    const claudePath = join(ROOT, TARGETS.claude.agents, file);
    writeFileSync(claudePath, renderClaudeAgent(fields, body, path));
    written.push(claudePath);

    const opencodePath = join(ROOT, TARGETS.opencode.agents, file);
    writeFileSync(opencodePath, renderOpencodeAgent(fields, body, path));
    written.push(opencodePath);

    const antigravityPath = join(ROOT, TARGETS.antigravity.agents, file);
    writeFileSync(antigravityPath, renderAntigravityAgent(fields, body, path));
    written.push(antigravityPath);
  }

  return written;
}

function syncSkills() {
  const source = join(HARNESS, "skills");
  const names = readdirSync(source).filter((d) => statSync(join(source, d)).isDirectory());
  const written = [];

  for (const target of Object.values(TARGETS)) {
    const base = join(ROOT, target.skills);
    mkdirSync(base, { recursive: true });
    for (const name of names) {
      const dst = join(base, name);
      // Replace rather than merge, so a file deleted from harness/ does not linger.
      if (existsSync(dst)) rmSync(dst, { recursive: true, force: true });
      copyTree(join(source, name), dst);
      written.push(dst);
    }
  }

  return written;
}

/**
 * Commands are copied file by file rather than as a tree: every target directory also
 * holds OpenSpec's own generated opsx workflows, which this script does not own and must
 * not delete.
 *
 * Claude Code and opencode get the file verbatim. Antigravity gets it de-templated (see
 * detemplatizeForAntigravity) and re-emitted with just the `description:` field its
 * `.agents/workflows/*.md` format uses — the source files here only ever carry that one
 * frontmatter field, so no other transform is needed.
 */
function syncCommands() {
  const source = join(HARNESS, "commands");
  if (!existsSync(source)) return [];

  const names = readdirSync(source).filter((f) => f.endsWith(".md")).sort();
  const written = [];

  for (const [tool, target] of Object.entries(TARGETS)) {
    const base = join(ROOT, target.commands);
    mkdirSync(base, { recursive: true });
    for (const name of names) {
      const src = join(source, name);
      const dst = join(base, name);

      if (tool !== "antigravity") {
        writeFileSync(dst, readFileSync(src));
      } else {
        const { frontmatter, body } = splitFrontmatter(readFileSync(src, "utf8"), src);
        const fields = parseFrontmatter(frontmatter, src);
        const description = foldedValue("description", require_(fields, "description", src));
        writeFileSync(dst, `---\n${description}\n---\n\n${detemplatizeForAntigravity(body).trimStart()}`);
      }

      written.push(dst);
    }
  }

  return written;
}

const files = [...syncAgents(), ...syncSkills(), ...syncCommands()];
for (const file of files) console.log(relative(ROOT, file).replaceAll("\\", "/"));
console.log(`\nSynced ${files.length} paths from harness/ to .claude/, .opencode/, and .agents/.`);
